package gen

import (
	"strings"
	"testing"
)

// Every method's types resolve to wire declarations, with enums as unions
// and watches typed by topic.
func TestGenerate(t *testing.T) {
	src, err := Generate("../../../../pkg/pier/wire")
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{
		"// Code generated by internal/api/tsgen",
		"export const PROTOCOL_VERSION = ",
		`export type SessionState = "creating" | "running" | "working" | "idle" | "parked" | "deleting" | "dead" | "failed";`,
		"export interface Session {",
		"  createdAt?: string;",
		"export interface CheckoutInfo extends Checkout {",
		`"overview.watch": { params: Empty; result: WatchResult<Overview> };`,
		`"overview": { params: Empty; data: Overview };`,
		`"sessions.resume": { params: SessionRef; result: null };`,
		"export interface ServerNotifications {",
		`"$/progress": ProgressParams;`,
		"export interface ClientNotifications {",
		`"client.activity": ClientActivity;`,
	} {
		if !strings.Contains(src, want) {
			t.Errorf("generated TypeScript lacks %q", want)
		}
	}
	if strings.Contains(src, "WatchResult[") {
		t.Error("Go generic instantiations must not leak into TypeScript")
	}
}
